#[cfg(test)]
mod tests {
    use super::*;
    use p3_field::extension::BinomialExtensionField;
    use p3_field::extension::HasTwoAdicBinomialExtension;
    use p3_field::{BasedVectorSpace, Field, PrimeCharacteristicRing, PrimeField64, TwoAdicField};

    fn check<F: TwoAdicField + PrimeField64 + HasTwoAdicBinomialExtension<4>>(m: u32) {
        assert_eq!(F::ORDER_U64, m as u64);
        let g = F::GENERATOR;
        // generator: g^((p-1)/q) != 1 for the prime factors q of p - 1
        let mut r = (m - 1) as u64;
        let mut q = 2u64;
        while r > 1 {
            if r % q == 0 {
                assert_ne!(g.exp_u64((m as u64 - 1) / q), F::ONE);
                while r % q == 0 {
                    r /= q;
                }
            }
            q += 1;
        }
        for bits in 0..=F::TWO_ADICITY {
            let w = F::two_adic_generator(bits);
            assert_eq!(w.exp_power_of_2(bits), F::ONE);
            if bits > 0 {
                assert_ne!(w.exp_power_of_2(bits - 1), F::ONE);
            }
        }
        type E<F> = BinomialExtensionField<F, 4>;
        let x = E::<F>::from_basis_coefficients_fn(|i| F::from_u32(3 * i as u32 + 7));
        assert_eq!(x * x.inverse(), E::<F>::ONE);
        assert_eq!(x.exp_u64(m as u64).exp_u64(m as u64).exp_u64(m as u64).exp_u64(m as u64), x, "Frobenius^4 = id");
        for bits in 0..=E::<F>::TWO_ADICITY {
            let w = E::<F>::two_adic_generator(bits);
            assert_eq!(w.exp_power_of_2(bits), E::<F>::ONE);
            if bits > 0 {
                assert_ne!(w.exp_power_of_2(bits - 1), E::<F>::ONE);
            }
        }
    }

    #[test]
    fn lane_fields_are_the_rns_moduli() {
        check::<Lane3>(ss_rap_v2::RNS_MODULI[2]);
        check::<Lane4>(ss_rap_v2::RNS_MODULI[3]);
        check::<Lane5>(ss_rap_v2::RNS_MODULI[4]);
        check::<p3_baby_bear::BabyBear>(ss_rap_v2::RNS_MODULI[0]);
        check::<p3_koala_bear::KoalaBear>(ss_rap_v2::RNS_MODULI[1]);
    }
}
